def transform(grid):
    h, w = len(grid), len(grid[0])

    # A solid nonzero row or column separates two matching regions.
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            a = grid[:r]
            b = grid[r + 1:]
            return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                     for j in range(w)] for i in range(len(a))]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            return [[2 if grid[r][j] != 0 and grid[r][c + 1 + j] != 0 else 0
                     for j in range(c)] for r in range(h)]

    return grid
